function control(state) {
  var MAXU = 0.1;
  if (!state || !state.tip || !state.target) return {action: 'stop', reason: 'missing state'};
  var tip = state.tip, target = state.target;
  if (!isFinite(tip[0]) || !isFinite(tip[1]) || !isFinite(target[0]) || !isFinite(target[1])) {
    return {action: 'stop', reason: 'non-finite state'};
  }
  var ex = target[0] - tip[0], ey = target[1] - tip[1];
  var dist = Math.sqrt(ex * ex + ey * ey);
  var tol = (state.tolerancePx != null) ? state.tolerancePx : 7;
  if (dist <= tol) return {action: 'verify'};
  if (typeof state.maxActions === 'number' && typeof state.step === 'number' && state.step >= state.maxActions) {
    return {action: 'stop', reason: 'action budget exhausted'};
  }
  var h = state.history || [];
  var W = 12;
  var start = Math.max(0, h.length - W);

  // most recent commanded sign per channel (used to alternate probes, escapes travel limits)
  var lastCmd = [0, 0];
  for (var k = h.length - 1; k >= 0 && (lastCmd[0] === 0 || lastCmd[1] === 0); k--) {
    var sk = h[k];
    if (!sk || !sk.command) continue;
    for (var c = 0; c < 2; c++) {
      if (lastCmd[c] === 0 && typeof sk.command[c] === 'number' && sk.command[c] !== 0) {
        lastCmd[c] = sk.command[c] > 0 ? 1 : -1;
      }
    }
  }

  var a00 = 0, a01 = 0, a11 = 0;
  var r00 = 0, r01 = 0, r10 = 0, r11 = 0;
  var e0 = 0, e1 = 0, cnt = 0;
  for (var i = start; i < h.length; i++) {
    var s = h[i];
    if (!s || !s.applied || !s.delta) continue;
    var u0 = s.applied[0], u1 = s.applied[1], d0 = s.delta[0], d1 = s.delta[1];
    if (!isFinite(u0) || !isFinite(u1) || !isFinite(d0) || !isFinite(d1)) continue;
    if (Math.abs(u0) + Math.abs(u1) < 1e-6) continue;
    a00 += u0 * u0; a01 += u0 * u1; a11 += u1 * u1;
    r00 += u0 * d0; r01 += u1 * d0;
    r10 += u0 * d1; r11 += u1 * d1;
    e0 += u0 * u0; e1 += u1 * u1;
    cnt++;
  }

  function probe() {
    // excite the less-excited channel, reversing its last command sign
    var c = (e0 <= e1) ? 0 : 1;
    var sign = (lastCmd[c] > 0) ? -1 : 1;
    if (c === 0) return {action: 'move', u: [sign * MAXU, 0]};
    return {action: 'move', u: [0, sign * MAXU]};
  }

  if (cnt < 2 || e0 < 1e-6 || e1 < 1e-6) return probe();

  var lam = 1e-4 * (1 + a00 + a11);
  var A00 = a00 + lam, A11 = a11 + lam, A01 = a01;
  var det = A00 * A11 - A01 * A01;
  if (!isFinite(det) || Math.abs(det) < 1e-10) return probe();

  // J = R * inv(A)
  var J00 = (A11 * r00 - A01 * r01) / det;
  var J01 = (-A01 * r00 + A00 * r01) / det;
  var J10 = (A11 * r10 - A01 * r11) / det;
  var J11 = (-A01 * r10 + A00 * r11) / det;
  var jdet = J00 * J11 - J01 * J10;
  var jnorm = J00 * J00 + J01 * J01 + J10 * J10 + J11 * J11;
  if (!isFinite(jdet) || !isFinite(jnorm) || jnorm <= 0 || Math.abs(jdet) < 1e-3 * jnorm) {
    return probe();
  }

  // solve J u = e
  var ux = (J11 * ex - J01 * ey) / jdet;
  var uy = (-J10 * ex + J00 * ey) / jdet;
  if (!isFinite(ux) || !isFinite(uy)) return probe();

  var cap = (dist < 3 * tol) ? 0.05 : MAXU;
  var mag = Math.max(Math.abs(ux), Math.abs(uy));
  if (mag > cap) {
    ux = ux * cap / mag;
    uy = uy * cap / mag;
  }
  if (Math.abs(ux) > MAXU) ux = (ux > 0 ? MAXU : -MAXU);
  if (Math.abs(uy) > MAXU) uy = (uy > 0 ? MAXU : -MAXU);
  return {action: 'move', u: [ux, uy]};
}

function control(state) {
  var tip = state.tip;
  var tgt = state.target;
  if (!tip || !tgt || !isFinite(tip[0]) || !isFinite(tip[1]) || !isFinite(tgt[0]) || !isFinite(tgt[1])) {
    return { action: "stop", reason: "missing points" };
  }
  var ex = tgt[0] - tip[0];
  var ey = tgt[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) return { action: "stop", reason: "non-finite error" };
  if (err <= state.tolerancePx) return { action: "verify" };

  var h = state.history || [];

  // 全歷史中每個通道是否曾被有效激發，用於探測
  var c0 = 0, c1 = 0;
  for (var k = 0; k < h.length; k++) {
    var r = h[k];
    if (!r || !r.applied || !r.delta) continue;
    if (Math.abs(r.applied[0]) > 0.01 && isFinite(r.delta[0]) && isFinite(r.delta[1])) c0++;
    if (Math.abs(r.applied[1]) > 0.01 && isFinite(r.delta[0]) && isFinite(r.delta[1])) c1++;
  }
  var s = (h.length % 4 < 2) ? 1 : -1;
  if (c0 < 1) return { action: "move", u: [0.1 * s, 0] };
  if (c1 < 1) return { action: "move", u: [0, 0.1 * s] };

  // 局部擬合：只用最近的歷史（姿態會改變局部 Jacobian）；樣本不足時放寬視窗
  var windows = [12, 40];
  var J = null;
  for (var w = 0; w < windows.length && J === null; w++) {
    var start = Math.max(0, h.length - windows[w]);
    var A = [[1e-5, 0], [0, 1e-5]];
    var M = [[0, 0], [0, 0]];
    var n = 0;
    for (var q = start; q < h.length; q++) {
      var rec = h[q];
      if (!rec || !rec.applied || !rec.delta) continue;
      var a = rec.applied;
      var d = rec.delta;
      if (!isFinite(a[0]) || !isFinite(a[1]) || !isFinite(d[0]) || !isFinite(d[1])) continue;
      if (Math.abs(a[0]) + Math.abs(a[1]) < 1e-9) continue;
      n++;
      for (var i = 0; i < 2; i++) {
        for (var j = 0; j < 2; j++) {
          A[i][j] += a[i] * a[j];
          M[i][j] += d[i] * a[j];
        }
      }
    }
    if (n < 2) continue;
    var det = A[0][0] * A[1][1] - A[0][1] * A[1][0];
    if (!isFinite(det) || Math.abs(det) < 1e-12) continue;
    var inv = [[A[1][1] / det, -A[0][1] / det], [-A[1][0] / det, A[0][0] / det]];
    var Jc = [[0, 0], [0, 0]];
    for (var rr = 0; rr < 2; rr++) {
      for (var cc = 0; cc < 2; cc++) {
        Jc[rr][cc] = M[rr][0] * inv[0][cc] + M[rr][1] * inv[1][cc];
      }
    }
    var detJ = Jc[0][0] * Jc[1][1] - Jc[0][1] * Jc[1][0];
    if (isFinite(detJ) && Math.abs(detJ) > 1e-9) J = Jc;
  }

  if (J === null) {
    return { action: "move", u: [0.1 * s, 0.1 * s] };
  }

  var detJ2 = J[0][0] * J[1][1] - J[0][1] * J[1][0];
  var Ji = [[J[1][1] / detJ2, -J[0][1] / detJ2], [-J[1][0] / detJ2, J[0][0] / detJ2]];
  var u0 = 0.9 * (Ji[0][0] * ex + Ji[0][1] * ey);
  var u1 = 0.9 * (Ji[1][0] * ex + Ji[1][1] * ey);
  if (!isFinite(u0) || !isFinite(u1)) return { action: "stop", reason: "singular mapping" };

  // 每通道上限 0.1；大步長保持方向，接近時至少 0.01 以持續前進
  var m = Math.max(Math.abs(u0), Math.abs(u1));
  if (m > 0.1) {
    u0 = u0 * 0.1 / m;
    u1 = u1 * 0.1 / m;
  } else if (m > 0 && m < 0.01) {
    u0 = u0 * 0.01 / m;
    u1 = u1 * 0.01 / m;
  }
  u0 = Math.max(-0.1, Math.min(0.1, u0));
  u1 = Math.max(-0.1, Math.min(0.1, u1));
  return { action: "move", u: [u0, u1] };
}

function control(state) {
  var tip = state.tip, tgt = state.target;
  if (!tip || !tgt || !isFinite(tip[0]) || !isFinite(tip[1]) || !isFinite(tgt[0]) || !isFinite(tgt[1])) {
    return { action: "stop", reason: "missing tip or target" };
  }
  var ex = tgt[0] - tip[0], ey = tgt[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (typeof state.maxActions === "number" && typeof state.step === "number" && state.step >= state.maxActions) {
    return { action: "stop", reason: "action budget reached" };
  }
  if (err <= state.tolerancePx) {
    return { action: "verify" };
  }
  var h = state.history || [];
  var start = Math.max(0, h.length - 10);
  var cc00 = 0, cc01 = 0, cc11 = 0;
  var dc00 = 0, dc01 = 0, dc10 = 0, dc11 = 0;
  for (var i = start; i < h.length; i++) {
    var c = h[i].applied, d = h[i].delta;
    if (!c || !d || c.length !== 2 || d.length !== 2) continue;
    if (!isFinite(c[0]) || !isFinite(c[1]) || !isFinite(d[0]) || !isFinite(d[1])) continue;
    cc00 += c[0] * c[0];
    cc01 += c[0] * c[1];
    cc11 += c[1] * c[1];
    dc00 += d[0] * c[0];
    dc01 += d[0] * c[1];
    dc10 += d[1] * c[0];
    dc11 += d[1] * c[1];
  }
  // Excitation: probe the less-excited channel, alternating sign by history parity
  // so that a channel stuck at a travel limit is also tested in the opposite direction.
  var sign = (h.length % 2 === 0) ? 1 : -1;
  if (cc00 < 1e-4 || cc11 < 1e-4) {
    var ch = (cc00 <= cc11) ? 0 : 1;
    return ch === 0 ? { action: "move", u: [0.1 * sign, 0] } : { action: "move", u: [0, 0.1 * sign] };
  }
  // Least-squares Jacobian J (delta = J * u) from the recent window: J = D * inv(C C^T)
  var reg = 1e-6 * (cc00 + cc11) + 1e-12;
  var a = cc00 + reg, b = cc01, c2 = cc11 + reg;
  var det = a * c2 - b * b;
  if (!(det > 0) || !isFinite(det)) {
    return { action: "move", u: [0.1 * sign, 0] };
  }
  var i00 = c2 / det, i01 = -b / det, i10 = -b / det, i11 = a / det;
  var J00 = dc00 * i00 + dc01 * i10;
  var J01 = dc00 * i01 + dc01 * i11;
  var J10 = dc10 * i00 + dc11 * i10;
  var J11 = dc10 * i01 + dc11 * i11;
  var jn = J00 * J00 + J01 * J01 + J10 * J10 + J11 * J11;
  if (!isFinite(jn) || jn < 1e-8) {
    // no usable motion observed yet: probe alternately
    return { action: "move", u: [0.1 * sign, 0.1 * sign * 0.5] };
  }
  // Damped least squares: u = J^T (J J^T + lam I)^-1 e
  var m00 = J00 * J00 + J01 * J01;
  var m01 = J00 * J10 + J01 * J11;
  var m11 = J10 * J10 + J11 * J11;
  var lam = 1e-3 * (m00 + m11) + 1e-9;
  var p00 = m00 + lam, p11 = m11 + lam;
  var pdet = p00 * p11 - m01 * m01;
  if (!(Math.abs(pdet) > 0) || !isFinite(pdet)) {
    return { action: "stop", reason: "singular jacobian" };
  }
  var z0 = (p11 * ex - m01 * ey) / pdet;
  var z1 = (-m01 * ex + p00 * ey) / pdet;
  var u0 = J00 * z0 + J10 * z1;
  var u1 = J01 * z0 + J11 * z1;
  var mag = Math.max(Math.abs(u0), Math.abs(u1));
  if (!(mag > 0) || !isFinite(mag)) {
    return { action: "stop", reason: "no usable jacobian direction" };
  }
  var s = Math.min(1, 0.1 / mag);
  if (err < 3 * state.tolerancePx) {
    s *= 0.5;
  }
  var out0 = u0 * s, out1 = u1 * s;
  if (!isFinite(out0) || !isFinite(out1)) {
    return { action: "stop", reason: "non-finite command" };
  }
  out0 = Math.max(-0.1, Math.min(0.1, out0));
  out1 = Math.max(-0.1, Math.min(0.1, out1));
  return { action: "move", u: [out0, out1] };
}
